"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[201],{9513:e=>{e.exports=JSON.parse('{"functions":[{"name":"Query","desc":"Returns the ID and the value it currently has with the given components.\\n\\n```lua\\nECS.CreateComponent(\\"Test1\\", 100)\\nECS.CreateComponent(\\"Test2\\", true)\\nECS.NewEntity()\\nECS.NewEntity()\\n\\nlocal id = ECS.NewEntity()\\n\\nECS.GiveComponent(id, \\"Test1\\")\\n\\nfor i, v in ECS.Query(\\"Test1\\")\\n\\tprint(i, v) -- 3 100\\n\\t-- Only the third entity is looped over\\nend\\n```","params":[{"name":"...","desc":"Names of components","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Iterator"}],"function_type":"static","tags":["Iterator"],"errors":[{"lua_type":"Missing arguments","desc":"No arguments were provided to the function"}],"source":{"line":581,"path":"src/RomalsECS.luau"}},{"name":"NewEntity","desc":"Creates a new entity and returns the ID and Entity type, optional instance to bind it to.","params":[{"name":"instance","desc":"","lua_type":"Instance?"}],"returns":[{"desc":"The ID of the Entity","lua_type":"number"},{"desc":"The Entity table","lua_type":"Entity<Instance>"}],"function_type":"static","source":{"line":616,"path":"src/RomalsECS.luau"}},{"name":"BulkNewEntities","desc":"Creates multiple entities at once, if instanceArray is nil, n is used, if both are\\nnil, only one entity is created and returned, ... is the names of the components\\nthat are given when creating the entities.","params":[{"name":"n","desc":"Defaults to 1","lua_type":"number?"},{"name":"instanceArray","desc":"Priority over n","lua_type":"{Instance}?"},{"name":"...","desc":"Components to be given upon creation","lua_type":"string?"}],"returns":[{"desc":"List of IDs of the entities created","lua_type":"{number}"}],"function_type":"static","source":{"line":654,"path":"src/RomalsECS.luau"}},{"name":"BindToInstance","desc":"Binds an entity to an instance, if no instance is provided then\\nthe current instance binded to the entity is unbinded from it.","params":[{"name":"id","desc":"Entity ID","lua_type":"number"},{"name":"instance","desc":"Instance to bind to, nil if unbinding","lua_type":"Instance?"}],"returns":[],"function_type":"static","source":{"line":744,"path":"src/RomalsECS.luau"}},{"name":"GetEntity","desc":"Returns the entity with the given ID.","params":[{"name":"id","desc":"ID of Entity","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Entity<Instance>"}],"function_type":"static","source":{"line":769,"path":"src/RomalsECS.luau"}},{"name":"RemoveEntity","desc":"Removes an entity.","params":[{"name":"id","desc":"ID of Entity","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":778,"path":"src/RomalsECS.luau"}},{"name":"ClearAllEntities","desc":"Removes all the existing entities.","params":[],"returns":[],"function_type":"static","source":{"line":801,"path":"src/RomalsECS.luau"}},{"name":"GetAllIDs","desc":"Returns all the existing IDs of all entities.","params":[],"returns":[{"desc":"Array of IDs","lua_type":"{number}"}],"function_type":"static","source":{"line":819,"path":"src/RomalsECS.luau"}},{"name":"CreateComponent","desc":"Creates a new component with value T, the value given to it will be the default that is\\nassigned to entities whenever they are given the component.\\n\\n\\n```lua\\nECS.CreateComponent(\\"Test\\", 1000) -- 1000 is the default value\\nECS.NewEntity()\\n\\nlocal component = ECS.GiveComponent(1, \\"Test\\")\\nprint(component.Value) -- 1000\\n```\\n\\nDifferent behavior is applied when the value is of type Instance. The default value of the component\\nwill be nil, entities that are given this component will also have a value of nil unless given a\\ndefault instance to use when calling GiveComponent().\\n\\n:::caution Invalid Values\\n`table`, `thread`, `userdata`, and `function` will cause the function to error, these types are not allowed\\nto be used for the value of the component.\\n:::","params":[{"name":"name","desc":"Name of component","lua_type":"string"},{"name":"value","desc":"Default value for the component","lua_type":"T"}],"returns":[],"function_type":"static","errors":[{"lua_type":"Invalid value","desc":"Value given is an invalid value"},{"lua_type":"Exceeded maximum","desc":"There is a maximum of 32 components that can be created"},{"lua_type":"Already existing componnet","desc":"A component with the same name already exists"}],"source":{"line":857,"path":"src/RomalsECS.luau"}},{"name":"DestroyComponent","desc":"Destroys the component, entities with this component will have it removed, frees up space for\\nthe creation of another component.","params":[{"name":"name","desc":"Name of component","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":892,"path":"src/RomalsECS.luau"}},{"name":"RemoveComponent","desc":"Removes a component from a given entity.","params":[{"name":"id","desc":"Remove component from an entity","lua_type":"number"},{"name":"name","desc":"Name of component to remove","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":917,"path":"src/RomalsECS.luau"}},{"name":"GiveComponent","desc":"Gives the component to the given entity, returns the component. If the component\\nwas created with a default value of type Instance then the default value will\\nbe nil if not given an Instance in the defaultInstance parameter. Providing a\\nvalue to the parameter on a component that isn\'t an Instance based component will\\ncause the parameter to be ignored.","params":[{"name":"id","desc":"ID of Entity","lua_type":"number"},{"name":"name","desc":"Name of component to give","lua_type":"string"},{"name":"defaultInstance","desc":"Default value for instance based components","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"Component<T>"}],"function_type":"static","source":{"line":941,"path":"src/RomalsECS.luau"}},{"name":"HasComponent","desc":"Checks if the given entity has the specified component.","params":[{"name":"id","desc":"ID of entity","lua_type":"number"},{"name":"name","desc":"Name of component","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":998,"path":"src/RomalsECS.luau"}}],"properties":[{"name":"_ENTITY_TAG_NAME","desc":"Name of the CollectionService tag given to instances bound to an entity.","lua_type":"string","readonly":true,"source":{"line":537,"path":"src/RomalsECS.luau"}},{"name":"_ENTITY_ID_STRING","desc":"Name of the attribute given to instances bound to an entity. The attribute holds the ID of the entity.","lua_type":"string","readonly":true,"source":{"line":545,"path":"src/RomalsECS.luau"}}],"types":[{"name":"Component<T>","desc":"ComponentChanged is read only, Value can be written to.\\n\\n```lua\\nECS.CreateComponent(\\"Test\\", 100)\\nECS.NewEntity()\\n\\nlocal component = ECS.GiveComponent(1, \\"Test\\")\\n\\ncomponent.ComponentChanged:Connect(function(newValue)\\n\\tprint(newValue) -- Prints 300\\nend)\\n\\ncomponent.Value = 300\\n```\\n\\nYou are able to get intellisense by casting the type.\\n\\n```lua\\nECS.CreateComponent(\\"Intellisense\\", true)\\nECS.NewEntity()\\n\\nlocal component = ECS.GiveComponent(1, \\"Intellisense\\") :: ECS.Component<boolean>\\n\\ncomponent.Value = false -- Valid\\ncomponent.Value = 100 -- Type error\\n```\\n\\nYou will get an error if you attempt to run the following code.\\n\\n```lua\\nECS.CreateComponent(\\"Errors\\", 0)\\nECS.NewEntity()\\n\\nlocal component = ECS.GiveComponent(1, \\"Errors\\")\\n\\ncomponent.ComponentChanged = \\"foo\\" -- Error\\ncomponent.NewKey = \\"bar\\" -- Error\\nprint(component.RealValue) -- Error\\n```","fields":[{"name":"Value","lua_type":"T","desc":""},{"name":"ComponentChanged","lua_type":"Event<T>","desc":""}],"source":{"line":507,"path":"src/RomalsECS.luau"}},{"name":"Entity<T>","desc":"An entity table, ComponentAdded and ComponentRemoved return the name of the component\\nthat was removed when calling functions connected to them. All of these values are read only.\\n\\nIntellisense is supported by casting the type\\n\\n```lua\\nlocal part = workspace.Part\\nlocal entity = select(-1, ECS.NewEntity(part)) :: ECS.Entity<BasePart>\\n\\nprint(entity.Instance.Position)\\n```","fields":[{"name":"Components","lua_type":"number","desc":""},{"name":"Instance","lua_type":"T?","desc":""},{"name":"ComponentAdded","lua_type":"Event<string>","desc":""},{"name":"ComponentRemoved","lua_type":"Event<string>","desc":""}],"source":{"line":529,"path":"src/RomalsECS.luau"}}],"name":"ECS","desc":"Romal\'s ECS module. Adds support for the ECS paradigm. Provides most common ECS features such as being able to query\\nentities.","source":{"line":552,"path":"src/RomalsECS.luau"}}')}}]);